{"code": "import os
from PIL import Image, UnidentifiedImageError

images_path = 'data_small/images/Images/'
if os.path.exists(images_path):
    all_files = []
    valid_count = 0
    corrupted_count = 0
    for root, dirs, files in os.walk(images_path):
        for f in files:
            if f.lower().endswith(('.jpg', '.jpeg', '.png')):
                all_files.append(os.path.join(root, f))

    print(f"Total image files found: {len(all_files)}")

    for path in all_files[:10]:  # Check first 10 files
        try:
            with Image.open(path) as img:
                img.verify()
            valid_count += 1
        except (UnidentifiedImageError, IOError, OSError) as e:
            corrupted_count += 1
            print(f"Corrupted: {path}")
            break

    print(f"Valid images (checked first 10): {valid_count}")
    print(f"Corrupted images (checked first 10): {corrupted_count}")
else:
    print(f"Path does not exist: {images_path}")"}

